    "bruteRange": "import sys\n\ninput = sys.stdin.readline  # đọc nhanh hơn, em cứ chép nguyên\n# Tách rồi đổi thành số nguyên.\nn, q = map(int, input().split())  # Đọc n và số câu hỏi.\na = [0] + list(map(int, input().split()))  # Đổi số; thêm ô 0 phía trước.\nanswer = []  # Lưu kết quả.\nfor _ in range(q):  # Lặp đúng q lần.\n    l, r = map(int, input().split())  # Đọc hai đầu đoạn.\n    total = 0  # Cộng lại từ đầu.\n    for i in range(l, r + 1):  # Duyệt đủ cả hai đầu đoạn.\n        total += a[i]  # Cộng thêm một số.\n    answer.append(str(total))  # str đổi số thành chữ.\nprint('\\n'.join(answer))  # join ghép các dòng kết quả.\n",
    "modelRange": "import sys\n\ninput = sys.stdin.readline  # đọc nhanh hơn, em cứ chép nguyên\n# Tách rồi đổi thành số nguyên.\nn, q = map(int, input().split())  # Đọc n và số câu hỏi.\na = [0] + list(map(int, input().split()))  # Đổi số; thêm ô 0 phía trước.\npre = [0] * (n + 1)  # Ô đầu giữ tổng bằng 0.\nfor i in range(1, n + 1):  # Duyệt từ 1 đến n.\n    pre[i] = pre[i - 1] + a[i]  # Tổng cũ cộng thêm số đang xét.\nanswer = []  # Lưu kết quả.\nfor _ in range(q):  # Lặp đúng q lần.\n    l, r = map(int, input().split())  # Đọc hai đầu đoạn.\n    total = pre[r] - pre[l - 1]  # Bỏ phần trước l, giữ a[l].\n    answer.append(str(total))  # str đổi số thành chữ.\nprint('\\n'.join(answer))  # join ghép các dòng kết quả.\n",
    "difference": "import sys\n\ninput = sys.stdin.readline  # đọc nhanh hơn, em cứ chép nguyên\n# Tách rồi đổi thành số nguyên.\nn, q = map(int, input().split())  # Đọc n và số lần cộng.\nd = [0] * (n + 2)  # Thêm ô n+1 để đánh dấu dừng.\nfor _ in range(q):  # Lặp đúng q lần.\n    l, r, x = map(int, input().split())  # Đọc đoạn và số cần cộng.\n    d[l] += x  # Bắt đầu cộng x tại l.\n    d[r + 1] -= x  # Dừng cộng x ngay sau r.\ncurrent = 0  # Tổng thay đổi đang có.\nanswer = []  # Lưu kết quả.\nfor i in range(1, n + 1):  # Duyệt từ 1 đến n.\n    current += d[i]  # Cộng dồn để khôi phục số này.\n    answer.append(current)  # Ghi thêm một kết quả.\nprint(*answer)  # * tách các số để in.\n"
